"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7989],{5928(a){a.exports=JSON.parse('{"title":"\ud504\ub860\ud2b8\uc5d4\ub4dc \uc544\ud0a4\ud14d\uccd0\uc5d0 \ub300\ud55c \uc0dd\uac01 ","date":"2024-02-20","coverUrl":null,"html":"<h2 data-notion-block-id=\\"bc31c13c-d967-46a5-88e2-6b487f1031d1\\" id=\\"bc31c13c-d967-46a5-88e2-6b487f1031d1\\">AWS LLRT \ub7f0\ud0c0\uc784 \ucd9c\uc2dc</h2><a href=\\"https://github.com/awslabs/llrt\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/awslabs/llrt</a><p data-notion-block-id=\\"1d8a4522-a413-44f8-bee4-56e3e5fb3117\\"><b>\uc2ec\uc724\uc12d</b>: AWS Lambda\uac00 \ub9ce\uc740 \uacf3\uc5d0\uc11c \uc778\uae30\ub97c \ub04c\uace0 \uc788\uc9c0\ub9cc \uc18d\ub3c4\uc640 cold start\ub294 \ud56d\uc0c1 \ub2e8\uc810\uc73c\ub85c \ub530\ub77c\uc635\ub2c8\ub2e4(<a href=\\"https://blog.cloudflare.com/cloudflare-workers-the-fast-serverless-platform\\">Cloudflare Workers\ub294 V8\uc744 \uae30\ubc18\uc73c\ub85c \ud55c \uc790\uccb4 \uc5d4\uc9c4\uc744 \uad6c\uc131\ud568</a>) \uc774\ub97c \uc704\ud574\uc11c Lambda\ub3c4 \uc0c8\ub85c\uc6b4 \ub7f0\ud0c0\uc784\uc744 \ucd9c\uc2dc\ud558\uc600\uc2b5\ub2c8\ub2e4. \uc774\uc81c serverless \ud50c\ub7ab\ud3fc\uc5d0\uc11c AWS Lambda\ucabd\uc5d0 \uc7a5\uc810\uc774 \ud558\ub098 \ucd94\uac00\ub420 \uc218\ub3c4 \uc788\uaca0\ub2e4\ub77c\ub294 \uc0dd\uac01\uc774 \ub4dc\ub124\uc694.</p><h2 data-notion-block-id=\\"5f302181-a327-4834-9ee5-047e17fe5a6e\\" id=\\"5f302181-a327-4834-9ee5-047e17fe5a6e\\">\ub9ac\uc561\ud2b8\uc5d0\uc11c \uc544\ud0a4\ud14d\uccd0</h2><a href=\\"https://alexkondov.com/full-stack-tao-clean-architecture-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexkondov.com/full-stack-tao-clean-architecture-react/</a><p data-notion-block-id=\\"053489d4-4b54-48f0-bcbb-608204ce10c8\\"><b>\uc2ec\uc724\uc12d</b>: \ub9ac\uc561\ud2b8 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c \uc2e4\uc81c \uc694\uad6c\uc0ac\ud56d\uc744 \uae30\ubc18\uc73c\ub85c \ub370\uc774\ud130\ub97c \uc5b4\ub5bb\uac8c \ubc1b\uc544\uc624\ub294 \ucf54\ub4dc, \uc870\uac74\ubd80 \ub80c\ub354\ub9c1 \ucf54\ub4dc\ub97c \ud6a8\uacfc\uc801\uc73c\ub85c \ubcf4\uc5ec\uc8fc\ub294 \ubc29\uc2dd\uc744 \uc790\uc2e0\uc758 \ub17c\ub9ac\ub97c \ubc14\ud0d5\uc73c\ub85c \uad6c\ud604\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub3c4, \ub2e4\ub978 \uae00\uc5d0\uc11c\ub3c4 \ub9d0\ud558\uc9c0\ub9cc \uc218\ub9ce\uc740 \uc544\ud0a4\ud14d\uccd0 \uc774\ub860\uc774 \uc788\uc9c0\ub9cc \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0 \uac78\ub9de\uace0 \uc790\uc2e0\uc758 \uc0c1\ud669\uc5d0 \uac78\ub9de\ub294 \uad6c\uc870\ub97c \ub9cc\ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uae00\uc5d0\uc11c\ub294 React-Query\ub85c \ub370\uc774\ud130 Fetching\uc744 \uad6c\uc0ac\ud558\uc9c0\ub9cc \ub2e4\ub978 Hook\uc744 \uac00\uc9c4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 Relay(GraphQL \uad6c\ud604\uccb4)\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\uace0 \uc5d0\ub7ec \ud578\ub4e4\ub9c1\uc774\ub098 \uc870\uac74\ubd80 \ub80c\ub354\ub9c1 \ub610\ud55c \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \ubaa8\ub450 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \uc790\uc2e0\uc758 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ub9de\ub294 \uad6c\uc870\ub97c \uc120\ud0dd\ud574\uc57c \ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"3dcf0c36-a072-4e2b-982b-66d8e1cc60f6\\"><b>\uae40\ub300\uad00</b>: \ud504\ub85c\ub355\ud2b8\ub97c \uac1c\ubc1c\ud560 \ub54c \uac00\uc7a5 \ub9ce\uc774 \ud558\ub294 \uace0\ubbfc\uc774 \ucf54\ub4dc\ub97c \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \ubd84\ud560\ud558\ub294\uac00?\ub97c \ub9ce\uc774 \uace0\ubbfc\ud569\ub2c8\ub2e4. \uae00\uc5d0\uc11c \ub9d0\ud558\ub294 \ub0b4\uc6a9 \uc911 \ubc31\uc5d4\ub4dc(\uc11c\ubc84)\uc5d0\uc11c \ub0b4\ub824\uc8fc\ub294 \ub370\uc774\ud130\ub97c \ud1b5\ud574 \ubcf4\uc5ec\uc8fc\ub294 \ud654\uba74\uc5d0\uc11c \uc5d0\ub7ec\ud578\ub4e4\ub9c1\uacfc \uc870\uac74\ubd80 \ub80c\ub354\ub9c1\uc744 \ucc98\ub9ac\ud558\ub294 \uac83\uc5d0 \ub530\ub77c\uc11c \uad6c\uc870\ub97c \ucee4\uc2a4\ud140\ud558\ub294\uac8c \uc911\uc694\ud558\ub2e4\ub294 \ub0b4\uc6a9\uc5d0 \ub9ce\uc740 \uacf5\uac10\uc774 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"8bdab1f2-ba18-4be5-862e-11b99fc53f46\\" id=\\"8bdab1f2-ba18-4be5-862e-11b99fc53f46\\">Protobuf\ub85c \uac1c\ubc1c \uacf5\uc218 \uc904\uc774\uae30</h2><a href=\\"https://blog.gangnamunni.com/post/saas-why-do-frontend-developers-design-api/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.gangnamunni.com/post/saas-why-do-frontend-developers-design-api/</a><p data-notion-block-id=\\"a435c3ed-d929-4b03-a51c-271f2547db3b\\"><b>\uc2ec\uc724\uc12d</b>: API \ubb38\uc11c\ub97c \uad00\ub9ac\ud558\uae30 \ubcf4\ub2e4\ub294 \uc778\ud130\ud398\uc774\uc2a4 \ud0c0\uc785(\uc5ec\uae30\uc11c\ub294 Protobuf)\uc744 \uc124\uacc4\ud55c \uc774\ud6c4 \uc774 \ud0c0\uc785\uc744 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 \ubc31\uc5d4\ub4dc\uc5d0 \uc801\uc6a9\ud574 type-safety\uc640 \ubb38\uc11c\ud654\ub97c \ub3d9\uc2dc\uc5d0 \ucc59\uae30\ub294 \uc774\uc810\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4. \ubb38\uc11c\ud654 \uc720\uc9c0\uc640 \ud504\ub860\ud2b8\uc5d4\ub4dc-\ubc31\uc5d4\ub4dc \ub3d9\uc2dc \uac1c\ubc1c\uc758 \uc5b4\ub824\uc6c0\uc744 \ud574\uacb0\ud558\ub294 \ubb38\uc81c \uc911 \ud558\ub098\ub85c \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4! \uc774\uc678\uc5d0\ub3c4 MSW\ub85c \ubaa8\ud0b9\uc744 \ud558\ub294 \ubc29\ubc95(<a href=\\"https://tech.kakao.com/2021/09/29/mocking-fe/\\">\ube14\ub85c\uadf8</a>), \uac19\uc740 \uc5b8\uc5b4\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95(<a href=\\"https://trpc.io/\\">trpc</a>, PHP, \u2026)\ub3c4 \uc788\uc73c\ub2c8 \uc5ec\ub7ec \ubc29\ubc95 \uc911 \uc801\ud569\ud55c \ud558\ub098\ub97c \ucc3e\ub294 \uac83\uc774 \uc911\uc694\ud558\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"445ad793-b076-4d0d-8a73-e379b5e76f64\\" id=\\"445ad793-b076-4d0d-8a73-e379b5e76f64\\">Git \uba85\ub839\uc5b4 \ud301</h2><a href=\\"https://blog.gitbutler.com/git-tips-and-tricks/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.gitbutler.com/git-tips-and-tricks/</a><p data-notion-block-id=\\"5b1139b9-d215-4343-9903-05bb10018594\\">GitBulter \ud300\uc758 \uc5ec\ub7ec\uac00\uc9c0 \uc54c\uba74 \uc88b\uc744\ub9cc\ud55c \uba85\ub839\uc5b4\uc640 \uae30\ub2a5\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \ubb3c\ub860 Git GUI Client\ub4e4\uc774 \ud6cc\ub96d\ud55c \uc5ed\ud560\uc744 \ud574\uc8fc\uc9c0\ub9cc \uc774\ub7f0 \uae30\ub2a5\ub3c4 \uc788\ub2e4\ub97c \uc54c\uc544\ub450\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"a9e04e87-0e20-45e9-b065-040dc1a47d81\\" id=\\"a9e04e87-0e20-45e9-b065-040dc1a47d81\\">Express\ud300 \uc77c\ud55c\ub2e4.</h2><a href=\\"https://github.com/expressjs/discussions/issues/160\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/expressjs/discussions/issues/160</a><p data-notion-block-id=\\"870d1404-12cc-41b5-8c25-71d92d8a8963\\">5.0 \uacc4\ud68d\uc744 2020\ub144\ub3c4\uc5d0 \ub0c8\ub294\ub370 \uc9c4\ud589\uc774 \uc548 \ub418\uace0 \uc788\uc5c8\ub294\ub370 \ub2e4\uc2dc \uc2dc\uc791\ud55c\ub2e4\ub294 \uc774\uc288\uac00 \uc0dd\uc131\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc544\uc9c1 \uac08 \uae38\uc740 \uba40\uc5b4\ubcf4\uc774\ub124\uc694.</p>"}')}}]);